const s=String($json.text??'').normalize('NFKC').trim();
const lower=s.toLocaleLowerCase('fr-FR');
const arabic=/[\u0600-\u06ff]/.test(s);
const latin=/[A-Za-z]/.test(s);
const mixed=/[\u0600-\u06ff]/.test(s)&&/[A-Za-z]/.test(s);
const tounsiHints=['chnowa','chneya','nheb','n7eb','behi','brabi','hedhi','hedha','zid','na7i','faragh','panier','souma','b9adech','bgadech','mawjoud','mawjouda','taille','commande','nekammel'];
const frenchHints=['bonjour','salut','prix','combien','disponible','taille','panier','commande','livraison','retour','remboursement','paiement'];
const tokens=lower.split(/[^a-z0-9À-ÿ7-9]+/).filter(Boolean);
const tnScore=tounsiHints.filter(x=>lower.includes(x)).length;
const frScore=frenchHints.filter(x=>lower.includes(x)).length;
let language=arabic?'ar':(tnScore>0?'tn':(frScore>0?'fr':'en'));
if(tnScore>0 && frScore>0) language='tn';
const script=arabic?'arabic':(latin?'latin':'unknown');
const register=/\b(bro|frere|haha|lol|stp|please|brabi)\b/i.test(s)?'casual':'neutral';
return [{json:{...$json,normalized_text:s,normalized_lower:lower,language,script,register,mixed_languages:mixed?['ar','latin']:[],tounsi_score:tnScore,french_score:frScore}}];

const t=$json.normalized_lower;
const cartSignals=/(panier|cart|السلة)/i.test(t);
const explicitSize=/\b(taille|size|taille)\s*(42|43|44|45|46|xs|s|m|l|xl|xxl)\b/i.test(t);
let override=$json.candidate_intent;
if (/(zidh|zid|add|ajoute|حط|زيد)/i.test(t)&&cartSignals) override='cart_add';
if (/(na7i|remove|delete|supprime|enl[eè]ve|نحي|احذف)/i.test(t)&&cartSignals) override='cart_remove';
if (/(badal|baddel|change|update|modifier|بدّل|غير)/i.test(t)&&explicitSize) override='cart_update';
if (/(faragh|vider|clear|empty|فرّغ)/i.test(t)&&cartSignals) override='cart_clear';
if (/(warini|show|view|voir|affiche)/i.test(t)&&cartSignals) override='cart_view';
if (/nekammel.*checkout|finaliser|passer.*commande|checkout/i.test(t)) override='checkout_start';
if (/(confirm|confirme|confirmer|أكد)/i.test(t)&&/(commande|order|checkout)/i.test(t)) override='checkout_confirm';
const clarification=override==='clarification'||$json.confidence<0.65;
return [{json:{...$json,intent:clarification?'clarification':override,needs_clarification:clarification,confidence:clarification?0.2:$json.confidence}}];
